template<class ForwardIt, class T>
ForwardIt std::lower_bound(ForwardIt first, ForwardIt last, const T& value);
// Implementation note: Assumes [first, last) is sorted in non-descending order. Uses binary search to return an iterator to the first element >= value.

template<class ForwardIt, class T>
ForwardIt std::upper_bound(ForwardIt first, ForwardIt last, const T& value);
// Implementation note: Similar to lower_bound, but returns an iterator to the first element > value. Relies on the same binary search mechanism for efficiency.
